import random
from fractions import Fraction as F

# Purple starts X ~ U[0,20], in bloom [X, X+4]; red starts Y ~ U[0,20], [Y, Y+8].
# They overlap  <=>  X < Y + 8 and Y < X + 4  <=>  -8 < X - Y < 4.

def area_below(c):                 # area of {(x,y) in [0,20]^2 : x - y < c}
    if c <= -20:
        return F(0)
    if c >= 20:
        return F(400)
    if c <= 0:
        return F((20 + c) ** 2, 2)
    return F(400) - F((20 - c) ** 2, 2)

exact = (area_below(4) - area_below(-8)) / 400

random.seed(0)
N = 3_000_000
hits = 0
for _ in range(N):
    x = random.uniform(0, 20)
    y = random.uniform(0, 20)
    if x < y + 8 and y < x + 4:
        hits += 1
print("CHECK", (str(exact), round(hits / N, 5)), "vs", ('1/2', 0.5))
